"""Shared finding type for agent project validation.

A :class:`ValidationFinding` is a single, self-describing authoring problem
discovered by a project check (a dangling ``next`` target, an undeclared memory
entry, a missing ``tools.py``, ...). Checks *return* findings rather than
raising, so :func:`rasa.mantle.validation.validate_project` can aggregate all
of them and report every problem at once — mirroring the v1 validator, which
collects results and raises a single terminal
:class:`~rasa.exceptions.ValidationError`.

Every finding carries a dot-namespaced ``code`` so callers (and tests) can key
off it without matching on the human-readable ``message``.
"""

from __future__ import annotations

from typing import Literal

from pydantic import BaseModel, ConfigDict

ValidationSeverity = Literal["error", "warning"]


class ValidationFinding(BaseModel):
    """A single authoring problem found while validating an agent project."""

    model_config = ConfigDict(frozen=True)

    code: str
    """Dot-namespaced identifier, e.g. ``mantle.validation.flow.unresolved_next``."""

    message: str
    """Actionable, human-readable description, including the offending location."""

    severity: ValidationSeverity = "error"
    """``error`` fails validation; ``warning`` is logged but does not block train."""

    docs_url: str | None = None
    """Optional link to docs explaining this finding."""
